async () => {
    const searches = await Promise.all([
      connecta.search({ query: "list organizations projects", safety: "readOnly", includeSchemas: "compact", limit: 100 }),
      connecta.search({ query: "organizations project analytics", safety: "readOnly", includeSchemas: "compact", limit: 100 })
    ]);
    const byAddress = new Map();
    for (const s of searches) for (const t of s.tools) byAddress.set(t.address, t);
    const ranked = [...byAddress.values()].filter(t =>
      /organization/i.test(t.address + " " + (t.description || ""))
    ).sort((a, b) => {
      const score = t => (/list/i.test(t.address) ? 4 : 0) +
        (/project/i.test(t.address + " " + (t.description || "")) ? 3 : 0) +
        (/analytics/i.test(t.address) ? 2 : 0);
      return score(b) - score(a);
    });
    if (!ranked.length) throw new Error("No organization-listing tool found");
    const details = await connecta.describe({ addresses: ranked.slice(0, 8).map(t => t.address) });
    const tools = details.tools || ranked;
    const keyNames = obj => {
      const out = [];
      const walk = x => {
        if (!x || typeof x !== "object") return;
        if (Array.isArray(x)) { for (const v of x) walk(v); return; }
        for (const [k, v] of Object.entries(x)) {
          if (/project/i.test(k)) out.push(k);
          walk(v);
        }
      };
      walk(obj);
      return [...new Set(out)];
    };
    for (const t of tools) {
      const explicit = [...(t.requiredInputKeys || []), ...(t.inputKeys || [])];
      const projectKey = explicit.find(k => /project/i.test(k)) ||
        keyNames(t).find(k => /^project(id|_id|key|slug|name)?$/i.test(k));
      if (!projectKey) continue;
      try {
        return await connecta.call(t.address, { [projectKey]: "mxp_eval_42" });
      } catch (e) {
        if (/auth_required/i.test(String(e))) throw e;
      }
    }
    throw new Error("No compatible organization-listing tool accepted the analytics project");
  }

